+3: 2
+4: 3
+5: 5
+
+$ gofib -n 3 -format json
+{"index":1,"fib":"1"}
+{"index":2,"fib":"1"}
+{"index":3,"fib":"2"}
+
+$ gofib -n 12 -format pretty
+ 1:   1
+ 2:   1
+ 3:   2
+ 4:   3
+ 5:   5
+ 6:   8
+ 7:  13
+ 8:  21
+ 9:  34
+10:  55
+11:  89
